  1→import { randomBytes } from "node:crypto";
  2→import { cookies } from "next/headers";
  3→import { redirect } from "next/navigation";
  4→import type { NextResponse } from "next/server";
  5→import { SESSION_COOKIE_NAME } from "@/lib/auth-config";
  6→import { getDb } from "@/lib/db";
  7→import { hashPassword } from "@/lib/password";
  8→import type { AuthUser, UserRecord, UserRole } from "@/lib/types";
  9→const SESSION_TTL_DAYS = 7;
 10→
 11→type UserRow = {
 12→  id: number;
 13→  username: string;
 14→  password: string;
 15→  role: UserRole;
 16→  departmentCode: string | null;
 17→  createdAt: string;
 18→  updatedAt: string;
 19→};
 20→
 21→function mapUserRow(row: UserRow | undefined): UserRecord | null {
 22→  if (!row) return null;
 23→  return {
 24→    id: row.id,
 25→    username: row.username,
 26→    role: row.role,
 27→    departmentCode: row.departmentCode,
 28→    createdAt: row.createdAt,
 29→    updatedAt: row.updatedAt,
 30→  };
 31→}
 32→
 33→export function getUserByUsername(username: string) {
 34→  const db = getDb();
 35→  return db
 36→    .prepare(
 37→      `SELECT
 38→        id,
 39→        username,
 40→        password,
 41→        role,
 42→        department_code as departmentCode,
 43→        created_at as createdAt,
 44→        updated_at as updatedAt
 45→      FROM users
 46→      WHERE username = ?`,
 47→    )
 48→    .get(username) as UserRow | undefined;
 49→}
 50→
 51→export function listUsers() {
 52→  const db = getDb();
 53→  return db
 54→    .prepare(
 55→      `SELECT
 56→        id,
 57→        username,
 58→        password,
 59→        role,
 60→        department_code as departmentCode,
 61→        created_at as createdAt,
 62→        updated_at as updatedAt
 63→      FROM users
 64→      ORDER BY role ASC, username ASC`,
 65→    )
 66→    .all()
 67→    .map((row) => mapUserRow(row as UserRow))
 68→    .filter((row): row is UserRecord => Boolean(row));
 69→}
 70→
 71→export function createUser(payload: {
 72→  username: string;
 73→  password: string;
 74→  role: UserRole;
 75→  departmentCode: string | null;
 76→}) {
 77→  const db = getDb();
 78→  const passwordHash = hashPassword(payload.password);
 79→  const result = db
 80→    .prepare(
 81→      `INSERT INTO users (username, password, role, department_code)
 82→       VALUES (?, ?, ?, ?)`,
 83→    )
 84→    .run(payload.username, passwordHash, payload.role, payload.departmentCode);
 85→
 86→  return getUserById(Number(result.lastInsertRowid));
 87→}
 88→
 89→export function updateUser(
 90→  userId: number,
 91→  payload: Partial<{ password: string; role: UserRole; departmentCode: string | null }>,
 92→) {
 93→  const db = getDb();
 94→  const current = getUserById(userId);
 95→  if (!current) return null;
 96→
 97→  const nextPassword = payload.password ? hashPassword(payload.password) : undefined;
 98→  db.prepare(
 99→    `UPDATE users
100→     SET password = COALESCE(?, password),
101→         role = COALESCE(?, role),
102→         department_code = ?,
103→         updated_at = CURRENT_TIMESTAMP
104→     WHERE id = ?`,
105→  ).run(
106→    nextPassword ?? null,
107→    payload.role ?? null,
108→    payload.departmentCode === undefined ? current.departmentCode : payload.departmentCode,
109→    userId,
110→  );
111→
112→  return getUserById(userId);
113→}
114→
115→export function getUserById(userId: number) {
116→  const db = getDb();
117→  const row = db
118→    .prepare(
119→      `SELECT
120→        id,
121→        username,
122→        password,
123→        role,
124→        department_code as departmentCode,
125→        created_at as createdAt,
126→        updated_at as updatedAt
127→      FROM users
128→      WHERE id = ?`,
129→    )
130→    .get(userId) as UserRow | undefined;
131→
132→  return mapUserRow(row);
133→}
134→
135→export function createSession(userId: number) {
136→  const db = getDb();
137→  const token = randomBytes(32).toString("hex");
138→  const expiresAt = new Date(Date.now() + SESSION_TTL_DAYS * 24 * 60 * 60 * 1000).toISOString();
139→  db.prepare(
140→    `INSERT INTO user_sessions (user_id, session_token, expires_at)
141→     VALUES (?, ?, ?)`,
142→  ).run(userId, token, expiresAt);
143→  return { token, expiresAt };
144→}
145→
146→export function deleteSession(token: string) {
147→  getDb().prepare(`DELETE FROM user_sessions WHERE session_token = ?`).run(token);
148→}
149→
150→export function getUserBySessionToken(token: string | undefined | null) {
151→  if (!token) return null;
152→  const db = getDb();
153→  const row = db
154→    .prepare(
155→      `SELECT
156→        u.id,
157→        u.username,
158→        u.password,
159→        u.role,
160→        u.department_code as departmentCode,
161→        u.created_at as createdAt,
162→        u.updated_at as updatedAt,
163→        s.expires_at as expiresAt
164→      FROM user_sessions s
165→      JOIN users u ON u.id = s.user_id
166→      WHERE s.session_token = ?`,
167→    )
168→    .get(token) as (UserRow & { expiresAt: string }) | undefined;
169→
170→  if (!row) return null;
171→  if (new Date(row.expiresAt).getTime() < Date.now()) {
172→    deleteSession(token);
173→    return null;
174→  }
175→
176→  return mapUserRow(row);
177→}
178→
179→export async function getCurrentUser() {
180→  const cookieStore = await cookies();
181→  return getUserBySessionToken(cookieStore.get(SESSION_COOKIE_NAME)?.value ?? null);
182→}
183→
184→export async function requireUser() {
185→  const user = await getCurrentUser();
186→  if (!user) {
187→    redirect("/login");
188→  }
189→  return user;
190→}
191→
192→export async function requireRole(roles: UserRole[]) {
193→  const user = await requireUser();
194→  if (!roles.includes(user.role)) {
195→    redirect("/");
196→  }
197→  return user;
198→}
199→
200→export function assertCanAccessDepartment(user: AuthUser, deptCode: string | null) {
201→  if (user.role === "DEAN") {
202→    return Boolean(deptCode && user.departmentCode === deptCode);
203→  }
204→  return true;
205→}
206→
207→export function attachSessionCookie(response: NextResponse, token: string, expiresAt: string) {
208→  response.cookies.set({
209→    name: SESSION_COOKIE_NAME,
210→    value: token,
211→    httpOnly: true,
212→    sameSite: "lax",
213→    secure: false,
214→    path: "/",
215→    expires: new Date(expiresAt),
216→  });
217→}
218→
219→export function clearSessionCookie(response: NextResponse) {
220→  response.cookies.set({
221→    name: SESSION_COOKIE_NAME,
222→    value: "",
223→    httpOnly: true,
224→    sameSite: "lax",
225→    secure: false,
226→    path: "/",
227→    expires: new Date(0),
228→  });
229→}
