@import "tailwindcss";
@import url('https://cdn.jsdelivr.net/gh/orioncactus/pretendard/dist/web/static/pretendard.min.css');

:root {
  /* Brand */
  --deep-green: #0a1f14;
  --primary-green: #1a6b4a;
  --gold: #c2a96a;
  --light-green: #e8f5ee;

  /* Surface */
  --page-bg: #f5f6f8;
  --card-bg: #ffffff;
  --row-hover: #fafbfc;
  --header-bg: #fafbfc;
  --divider: #f0f0f0;

  /* Text */
  --text-title: #111111;
  --text-body: #333333;
  --text-secondary: #888888;
  --text-disabled: #bbbbbb;

  /* Status */
  --status-complete: #1a6b4a;
  --status-progress: #c2a96a;
  --status-error: #e74c3c;
  --status-waiting: #bbbbbb;
  --status-review: #3b5fc0;

  /* Sidebar */
  --sidebar-bg: #0a1f14;
  --sidebar-text: #9bb5a6;
  --sidebar-text-active: #ffffff;
  --sidebar-hover: rgba(255, 255, 255, 0.1);
  --sidebar-section: #4a6e5a;

  /* Legacy compat */
  --background: var(--page-bg);
  --foreground: var(--text-body);
  --surface: var(--card-bg);
  --surface-strong: var(--card-bg);
  --line: var(--divider);
  --line-strong: var(--divider);
  --primary: var(--primary-green);
  --primary-strong: var(--deep-green);
  --accent: var(--gold);
  --muted-green: var(--light-green);
}

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --font-sans: 'Pretendard', 'Noto Sans KR', system-ui, -apple-system, sans-serif;
  --font-mono: "Consolas", "SFMono-Regular", monospace;
}

body {
  font-family: 'Pretendard', 'Noto Sans KR', system-ui, -apple-system, sans-serif;
  background: var(--page-bg);
  color: var(--text-body);
  margin: 0;
  user-select: text;
  -webkit-user-select: text;
}

* {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

button,
select,
textarea,
input {
  font: inherit;
}

::selection {
  background: rgba(26, 107, 74, 0.25);
  color: #111111;
}

::-moz-selection {
  background: rgba(26, 107, 74, 0.25);
  color: #111111;
}

td,
th,
p,
span,
h1,
h2,
h3,
h4,
h5,
h6,
label,
li,
a,
code {
  user-select: text;
  -webkit-user-select: text;
}

input,
textarea {
  user-select: text;
  -webkit-user-select: text;
  caret-color: var(--text-body);
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    scroll-behavior: auto !important;
    transition-duration: 0.01ms !important;
  }
}

/* Buttons */
.btn-primary {
  background: var(--deep-green);
  color: #fff;
  border: none;
  padding: 8px 18px;
  border-radius: 8px;
  font-size: 12px;
  font-weight: 500;
  cursor: pointer;
}
.btn-secondary {
  background: var(--card-bg);
  color: var(--text-body);
  border: 1px solid #ddd;
  padding: 8px 18px;
  border-radius: 8px;
  font-size: 12px;
  font-weight: 500;
  cursor: pointer;
}
.btn-danger {
  background: var(--status-error);
  color: #fff;
  border: none;
  padding: 8px 18px;
  border-radius: 8px;
  font-size: 12px;
  font-weight: 500;
  cursor: pointer;
}

/* Badge */
.badge {
  padding: 4px 10px;
  border-radius: 20px;
  font-size: 11px;
  font-weight: 500;
}
.badge-complete { background: var(--light-green); color: var(--status-complete); }
.badge-progress { background: #fef6e6; color: #b8941f; }
.badge-error { background: #fdeaea; color: #c0392b; }
.badge-waiting { background: #f0f0f0; color: var(--text-secondary); }
.badge-review { background: #e8edfb; color: var(--status-review); }

/* Card */
.card {
  background: var(--card-bg);
  border-radius: 10px;
  padding: 20px;
}

/* Input */
.input {
  padding: 8px 12px;
  border: 1px solid #ddd;
  border-radius: 8px;
  font-size: 12px;
  background: var(--card-bg);
  color: var(--text-body);
  outline: none;
}

/* Text Link */
.btn-link {
  background: none;
  border: none;
  color: var(--primary-green);
  text-decoration: underline;
  font-size: 12px;
  font-weight: 500;
  cursor: pointer;
  padding: 8px 18px;
}

"use client";

import { usePathname } from "next/navigation";
import Link from "next/link";
import Image from "next/image";
import type { AuthUser } from "@/lib/types";

type MenuItem = {
  label: string;
  href: string;
  /** Roles that should NOT see this item */
  hideFor?: string[];
};

const MENU_ITEMS: MenuItem[] = [
  { label: "계정관리", href: "/account", hideFor: ["DEAN"] },
  { label: "한 눈에 보는 채용 원테이블", href: "/" },
  { label: "(DB)후보자 관리", href: "/candidates" },
  { label: "(DB)관리자 페이지", href: "/admin", hideFor: ["DEAN"] },
  { label: "후보자 검증", href: "/verification" },
  { label: "채용 진행", href: "/hiring-progress" },
  { label: "채용 완료", href: "/hiring-complete" },
  { label: "학과장 Action", href: "/dean-action", hideFor: ["SUPER_ADMIN", "ADMIN"] },
];

function getVisibleMenu(role: string): MenuItem[] {
  return MENU_ITEMS.filter((item) => {
    if (item.hideFor && item.hideFor.includes(role)) return false;
    return true;
  });
}

function isActive(pathname: string, href: string): boolean {
  if (href === "/") return pathname === "/";
  return pathname === href || pathname.startsWith(href + "/");
}

export default function Sidebar({ user }: { user: AuthUser }) {
  const pathname = usePathname();
  const items = getVisibleMenu(user.role);

  return (
    <aside
      style={{
        width: 220,
        background: "var(--sidebar-bg)",
        padding: "20px 0",
        flexShrink: 0,
        position: "fixed",
        top: 0,
        left: 0,
        bottom: 0,
        display: "flex",
        flexDirection: "column",
        zIndex: 50,
        overflowY: "auto",
      }}
    >
      {/* Logo + Title */}
      <div style={{ padding: "0 16px 20px" }}>
        <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
          <div
            style={{
              width: 36,
              height: 36,
              borderRadius: "50%",
              background: "rgba(255,255,255,0.85)",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              flexShrink: 0,
            }}
          >
            <Image
              src="/logo_SKKU_colored.png"
              alt="SKKU"
              width={26}
              height={26}
              style={{ objectFit: "contain" }}
              unoptimized
            />
          </div>
          <div>
            <div
              style={{
                fontWeight: 700,
                fontSize: 14,
                color: "var(--sidebar-text-active)",
                lineHeight: 1.2,
              }}
            >
              교원채용
            </div>
            <div
              style={{
                fontSize: 10,
                color: "var(--sidebar-text)",
                marginTop: 2,
              }}
            >
              성균관대학교
            </div>
          </div>
        </div>
      </div>

      {/* Menu */}
      <nav style={{ flex: 1, padding: "0 8px" }}>
        {items.map((item) => {
          const active = isActive(pathname, item.href);
          return (
            <Link
              key={item.href + item.label}
              href={item.href}
              style={{
                display: "block",
                padding: "9px 12px",
                marginBottom: 2,
                borderRadius: 6,
                fontSize: 13,
                fontWeight: active ? 600 : 400,
                color: active
                  ? "var(--sidebar-text-active)"
                  : "var(--sidebar-text)",
                background: active ? "var(--sidebar-hover)" : "transparent",
                textDecoration: "none",
                transition: "background 0.15s, color 0.15s",
              }}
            >
              {item.label}
            </Link>
          );
        })}
      </nav>

      {/* User info at bottom */}
      <div
        style={{
          padding: "16px 16px 4px",
          borderTop: "1px solid rgba(255,255,255,0.08)",
        }}
      >
        <div
          style={{
            fontSize: 12,
            fontWeight: 600,
            color: "var(--sidebar-text-active)",
          }}
        >
          {user.username}
        </div>
        <div
          style={{
            fontSize: 10,
            color: "var(--sidebar-text)",
            marginTop: 2,
          }}
        >
          {user.role}
        </div>
      </div>
    </aside>
  );
}

